-- APEX: 17 everyday movements (ids 638-654) and better names for PDF import. Safe to run more than once.
do $$ begin
  if exists (select 1 from public.exercises where id between 638 and 654 and owner_coach_id is not null) then
    raise exception 'A custom exercise already uses an id between 638 and 654. Nothing was changed.';
  end if;
end $$;

